$mapText=(Invoke-WebRequest -UseBasicParsing -Uri 'https://raw.githubusercontent.com/trimcrae/Rare-cancers/da49c4e836533253825587f83656675dac4c913b/research/autonomy/data-opportunities-2026-09-30/deep-analysis/results/Foundation-complete-rearrangement-source-mapping.json').Content; $map=$mapText | ConvertFrom-Json; $records=@($map.result.REmapping.mapping); $emc=@($map.result.perEMC | ForEach-Object {[string]$_.sourceID}); $exportText=(Invoke-WebRequest -UseBasicParsing -Uri 'https://raw.githubusercontent.com/cBioPortal/datahub/dca75cb3f32b82d54a6f78bf0a6323e5b975aca1/public/sarcoma_msk_2022/data_sv.txt').Content; $export=@($exportText | ConvertFrom-Csv -Delimiter "`t"); $badOrdinal=0; $badGeneMap=0; $badID=0; $geneDifferences=@(); $NA=0; for($i=0;$i -lt $records.Count;$i++){ $m=$records[$i]; $e=$export[$i]; if($m.REordinal -ne ($i+1) -or $e.Sample_Id -ne ('sarcoma_msk_2022-'+($i+4)) -or $m.exportSampleID -ne $e.Sample_Id){$badOrdinal++}; if($e.Sample_Id -ne ('sarcoma_msk_2022-'+$m.sourceID)){$badID++}; $pair=@($e.Site1_Hugo_Symbol,$e.Site2_Hugo_Symbol); for($j=0;$j -lt 2;$j++){if($pair[$j] -eq 'N/A'){$NA++;$pair[$j]=''};if($pair[$j] -cne $m.exportGenePair[$j]){$badGeneMap++}}; if(($m.sourceGenePair -join '|') -cne ($pair -join '|')){$geneDifferences+= $m} }; $selected=@($records | Where-Object {$emc -contains ($_.exportSampleID -replace '^sarcoma_msk_2022-','')}); $true=@($records | Where-Object {$emc -contains $_.sourceID}); [pscustomobject]@{mappingRecords=$records.Count;exportRecords=$export.Count;badOrdinal=$badOrdinal;badExportGeneMap=$badGeneMap;changedIDs=$badID;distinctSourceIDs=@($records.sourceID | Sort-Object -Unique).Count;literalGeneDifferences=$geneDifferences.Count;NA=$NA;emcIDs=$emc.Count;sourceEMCEvents=$true.Count;selectedExportEvents=$selected.Count;selectedOriginatingEMC=@($selected | Where-Object {$emc -contains $_.sourceID}).Count;discordantEMCEvents=@($true | Where-Object {$_.exportSampleID -ne ('sarcoma_msk_2022-'+$_.sourceID)}).Count;EMCIDsAbove3774=@($emc | Where-Object {[int]$_ -gt 3774}).Count;coincidentRecord=@($records | Where-Object {$_.exportSampleID -eq ('sarcoma_msk_2022-'+$_.sourceID)})} | ConvertTo-Json -Depth 6
